INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist HTTP ein zustandsloses Protokoll?', 2, '[{"text": "Ja", "correct": true, "because": "HTTP speichert keinen Zustand zwischen Anfragen"}, {"text": "Nein", "correct": false, "because": "Zustandslosigkeit ist eine Kernfunktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Verwendet HTTP standardmäßig den Port 80?', 2, '[{"text": "Ja", "correct": true, "because": "Port 80 ist der Standardport für HTTP"}, {"text": "Nein", "correct": false, "because": "80 ist festgelegt"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist HTTP verschlüsselt?', 2, '[{"text": "Nein", "correct": true, "because": "HTTP überträgt Daten im Klartext, HTTPS ist verschlüsselt"}, {"text": "Ja", "correct": false, "because": "Verschlüsselung fehlt bei HTTP"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann HTTP Anfragen ohne Antwort verarbeiten?', 2, '[{"text": "Nein", "correct": true, "because": "HTTP ist ein Anfrage-Antwort-Protokoll"}, {"text": "Ja", "correct": false, "because": "Antwort ist zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Wird HTTP auf der Anwendungsschicht des OSI-Modells eingesetzt?', 2, '[{"text": "Ja", "correct": true, "because": "HTTP ist ein Anwendungsschichtprotokoll"}, {"text": "Nein", "correct": false, "because": "Anwendungsschicht ist korrekt"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Methode wird am häufigsten verwendet, um Daten mit HTTP abzurufen?', 2, '[{"text": "GET", "correct": true, "because": "GET ruft Daten vom Server ab"}, {"text": "POST", "correct": false, "because": "POST sendet Daten"}, {"text": "PUT", "correct": false, "because": "PUT aktualisiert Daten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Statuscode bedeutet, dass eine HTTP-Anfrage erfolgreich war?', 3, '[{"text": "200 OK", "correct": true, "because": "200 zeigt Erfolg an"}, {"text": "404 Not Found", "correct": false, "because": "404 bedeutet nicht gefunden"}, {"text": "500 Internal Server Error", "correct": false, "because": "500 zeigt einen Fehler"}]'),
('00000000-0000-0000-0000-000000000000', 'Auf welcher Transportschichtprotokoll basiert HTTP üblicherweise?', 2, '[{"text": "TCP", "correct": true, "because": "HTTP nutzt TCP für zuverlässige Übertragung"}, {"text": "UDP", "correct": false, "because": "UDP ist nicht üblich"}, {"text": "ICMP", "correct": false, "because": "ICMP ist für Diagnosen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche HTTP-Methode wird verwendet, um Daten an den Server zu senden?', 2, '[{"text": "POST", "correct": true, "because": "POST sendet Daten zur Verarbeitung"}, {"text": "GET", "correct": false, "because": "GET ruft nur Daten"}, {"text": "DELETE", "correct": false, "because": "DELETE entfernt Daten"}]'),
('00000000-0000-0000-0000-000000000000', 'Was bedeutet der HTTP-Statuscode 403?', 2, '[{"text": "Zugriff verweigert", "correct": true, "because": "403 zeigt fehlende Berechtigung"}, {"text": "Seite nicht gefunden", "correct": false, "because": "Das wäre 404"}, {"text": "Serverfehler", "correct": false, "because": "Das wäre 500"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat HTTP?', 4, '[{"text": "Zustandslos", "correct": true, "because": "Keine Speicherung zwischen Anfragen"}, {"text": "Anfrage-Antwort-basiert", "correct": true, "because": "Client-Server-Modell"}, {"text": "Verschlüsselt", "correct": false, "because": "Verschlüsselung ist HTTPS"}, {"text": "Textbasiert", "correct": true, "because": "HTTP-Nachrichten sind lesbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche HTTP-Methoden gibt es?', 3, '[{"text": "GET", "correct": true, "because": "Abrufen von Daten"}, {"text": "POST", "correct": true, "because": "Senden von Daten"}, {"text": "PUT", "correct": true, "because": "Aktualisieren von Daten"}, {"text": "SEND", "correct": false, "because": "Keine echte Methode"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Statuscodes zeigen Probleme an?', 4, '[{"text": "404 Not Found", "correct": true, "because": "Ressource nicht gefunden"}, {"text": "500 Internal Server Error", "correct": true, "because": "Serverseitiger Fehler"}, {"text": "200 OK", "correct": false, "because": "Erfolg, kein Problem"}, {"text": "403 Forbidden", "correct": true, "because": "Zugriff verweigert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bestandteile hat eine HTTP-Anfrage?', 3, '[{"text": "Anfragemethode", "correct": true, "because": "z. B. GET oder POST"}, {"text": "URL", "correct": true, "because": "Ziel der Anfrage"}, {"text": "Header", "correct": true, "because": "Zusätzliche Metadaten"}, {"text": "Prüfsumme", "correct": false, "because": "Nicht Teil von HTTP"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anwendungen nutzen HTTP?', 3, '[{"text": "Webbrowser", "correct": true, "because": "Abruf von Webseiten"}, {"text": "REST-APIs", "correct": true, "because": "Datenkommunikation"}, {"text": "DNS-Abfragen", "correct": false, "because": "DNS nutzt UDP/TCP"}, {"text": "Webserver", "correct": true, "because": "Bereitstellung von Inhalten"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) HTTP ist zustandslos. b) HTTP verwendet UDP als Transportprotokoll.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zustandslos ja, UDP nein (TCP)"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) HTTP nutzt Port 80. b) HTTP ist verschlüsselt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Port 80 ja, Verschlüsselung nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Der Statuscode 200 bedeutet Erfolg. b) POST wird zum Abrufen von Daten verwendet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "200 ja, POST sendet Daten"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) HTTP arbeitet auf der Anwendungsschicht. b) Der Statuscode 404 bedeutet Zugriff verweigert.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Anwendungsschicht ja, 404 ist nicht gefunden"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) HTTP verwendet ein Anfrage-Antwort-Modell. b) HTTP ist für Echtzeit-Streaming optimiert.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Anfrage-Antwort ja, Streaming ist UDP"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

